macro_rules! deps {
    () => {
        DefaultKind!();
    };
}

macro_rules! emulate_default_handler {
    () => {
        deps!();
        # [doc = " Emulates the behaviour of a default handler for the provided signal."] # [doc = ""] # [doc = " This function does its best to provide the same action as the default handler would do, without"] # [doc = " disrupting the rest of the handling of such signal in the application. It is also"] # [doc = " async-signal-safe."] # [doc = ""] # [doc = " This function necessarily looks up the appropriate action in a table. That means it is possible"] # [doc = " your system has a signal that is not known to this function. In such case an error is returned"] # [doc = " (equivalent of `EINVAL`)."] # [doc = ""] # [doc = " See also the [`register_conditional_default`][crate::flag::register_conditional_default]."] # [doc = ""] # [doc = " # Warning"] # [doc = ""] # [doc = " There's a short race condition in case of signals that terminate (either with or without a core"] # [doc = " dump). The emulation first resets the signal handler back to default (as the application is"] # [doc = " going to end, it's not a problem) and invokes it. But if some other thread installs a signal"] # [doc = " handler in the meantime (without assistance from `signal-hook`), it can happen this will be"] # [doc = " invoked by the re-raised signal."] # [doc = ""] # [doc = " This function will still terminate the application (there's a fallback on `abort`), the risk is"] # [doc = " invoking the newly installed signal handler. Note that manipulating the low-level signals is"] # [doc = " always racy in a multi-threaded program, therefore the described situation is already"] # [doc = " discouraged."] # [doc = ""] # [doc = " If you are uneasy about such race condition, the recommendation is to run relevant termination"] # [doc = " routine manually ([`exit`][super::exit] or [`abort`][super::abort]); they always do what they"] # [doc = " say, but slightly differ in externally observable behaviour from termination by a signal (the"] # [doc = " exit code will specify that the application exited, not that it terminated with a signal in the"] # [doc = " first case, and `abort` terminates on `SIGABRT`, so the detected termination signal may be"] # [doc = " different)."] pub fn emulate_default_handler (signal : c_int) -> Result < () , Error > { # [cfg (not (windows))] { if signal == SIGSTOP || signal == SIGKILL { return low_level :: raise (signal) ; } } let kind = DETAILS . iter () . find (| d | d . signal == signal) . map (| d | d . default_kind) . ok_or_else (| | Error :: from_raw_os_error (EINVAL)) ? ; match kind { DefaultKind :: Ignore => Ok (()) , # [cfg (not (windows))] DefaultKind :: Stop => low_level :: raise (SIGSTOP) , DefaultKind :: Term => { if let Ok (()) = restore_default (signal) { # [cfg (not (windows))] unsafe { # [allow (deprecated)] let mut newsigs : sigset_t = mem :: zeroed () ; # [cfg (all (target_os = "android" , target_pointer_width = "32"))] unsafe fn prepare_sigset (set : * mut sigset_t , mut signal : c_int) { signal -= 1 ; let set_raw : * mut libc :: c_ulong = set . cast () ; let size = mem :: size_of :: < libc :: c_ulong > () ; assert_eq ! (set_raw as usize % mem :: align_of ::< libc :: c_ulong > () , 0) ; let pos = signal as usize / size ; assert ! (pos < mem :: size_of ::< sigset_t > () / size) ; let bit = 1 << (signal as usize % size) ; set_raw . add (pos) . write (bit) ; } # [cfg (not (all (target_os = "android" , target_pointer_width = "32")))] unsafe fn prepare_sigset (set : * mut sigset_t , signal : c_int) { libc :: sigemptyset (set) ; libc :: sigaddset (set , signal) ; } prepare_sigset (& mut newsigs , signal) ; libc :: sigprocmask (SIG_UNBLOCK , & newsigs , ptr :: null_mut ()) ; } let _ = low_level :: raise (signal) ; } unsafe { libc :: abort () } } } }
    };
}

emulate_default_handler!()